const D = { density:.5, scale:1, speed:1, energy:.6, hue:280, x:.5, y:.5, style:'feedback', seed:0, rot:.5, drift:.5, act:'bloom' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const st = P.style;
const ink = (st==='ink');

// ---- ping-pong feedback buffers (size + seed keyed) ----
const fkey = width+'x'+height;
if (!S.a || S.fkey!==fkey){
  if (S.a&&S.a.remove) S.a.remove(); if (S.b&&S.b.remove) S.b.remove();
  S.a=createGraphics(width,height); S.a.colorMode(HSB,360,100,100,100);
  S.b=createGraphics(width,height); S.b.colorMode(HSB,360,100,100,100);
  S.fkey=fkey; S.seedUsed=null; S.styleUsed=null;
}
if (S.seedUsed!==P.seed || S.styleUsed!==st){
  S.seedUsed=P.seed; S.styleUsed=st;
  const base = ink ? [42,10,88] : (st==='thermal'?[248,55,12] : st==='oil'?[230,45,12] : [P.hue,25,14]);
  S.a.background(base[0],base[1],base[2]); S.b.background(base[0],base[1],base[2]);
  // seed attractor particles
  const N=48; S.px=[]; S.py=[]; S.ph=[];
  for (let i=0;i<N;i++){ S.px[i]=fr(i*5+1)*width; S.py[i]=fr(i*5+2)*height; S.ph[i]=fr(i*5+3); }
  // pre-stamp a few blooms so the frame is never blank
  S.a.noStroke();
  for (let i=0;i<10;i++){ const x=fr(i*9+7)*width, y=fr(i*9+8)*height, rr=u*(0.05+fr(i*9+9)*0.12); S.a.fill((P.hue+fr(i)*80)%360,70,ink?30:90, ink?24:40); S.a.ellipse(x,y,rr,rr); }
  S.b.image(S.a,0,0);
}

let src=S.a, dst=S.b;

// ---- feedback re-stamp: draw src into dst, scaled + rotated + faded ----
const cx=P.x*width, cy=P.y*height;
const kick = K.pulse*0.6 + A.bass*0.8;
const zoomAmt = (P.act==='pulse') ? (0.006 + kick*0.02) : 0.004;
const zoom = 1 + (zoomAmt + 0.004*(P.scale-1)) * P.speed + (P.act==='bloom'?0.002:0);
const spin = (P.rot-0.5) * (0.010 + 0.006*Math.sin(K.t*0.15)) * P.speed + (P.act==='vortex'?0.006*P.speed:0);
dst.push();
dst.translate(cx,cy); dst.rotate(spin); dst.scale(zoom); dst.translate(-cx,-cy);
if (ink){ dst.image(src,0,0); dst.noStroke(); dst.fill(42,9,90,10); dst.rect(0,0,width,height); } // decay toward cream
else { dst.tint(0,0,95.5,100); dst.image(src,0,0); dst.noTint(); }
dst.pop();
// ambient floor so buffer never blacks out below luminance gate
dst.noStroke();
if (ink){ dst.fill(42,9,88,4); } else { dst.fill(st==='thermal'?248:st==='oil'?230:P.hue, 32, 15, 9); }
dst.rect(0,0,width,height);

// ---- brush attractors deposit onto dst ----
const nB = Math.round(14 + P.density*46);
const drift = 0.3 + P.drift*1.4;
const hbase = (P.hue + K.t*(4+P.drift*10) + K.section*18) % 360;
dst.noStroke();
dst.blendMode(ink ? BLEND : (st==='oil'?SCREEN:ADD));
for (let i=0;i<nB;i++){
  const ph=S.ph[i];
  // curl-ish flow field, seed + time driven (continuous real-time motion)
  const fx = S.px[i]/u, fy = S.py[i]/u, tt = K.t*0.25*P.speed;
  const ang = (Math.sin(fx*2.1+tt+ph*6.28) + Math.cos(fy*1.7 - tt*0.8 + ph*3.1) + Math.sin((fx+fy)*1.3 + i)) * 2.0;
  const step = u*0.006*drift*P.speed*(0.6+A.rms*1.4);
  S.px[i]+=Math.cos(ang)*step + (cx-S.px[i])*0.002;
  S.py[i]+=Math.sin(ang)*step + (cy-S.py[i])*0.002;
  if (S.px[i]<0)S.px[i]+=width; if (S.px[i]>=width)S.px[i]-=width;
  if (S.py[i]<0)S.py[i]+=height; if (S.py[i]>=height)S.py[i]-=height;
  const sz = u*(0.012 + ph*0.03) * P.scale * (0.7+0.5*K.swell) * (0.8+kick*0.9);
  let h, s, b, a;
  if (ink){ h=(hbase+ph*30)%360; s=18+ph*22; b=14+ph*20; a=14+P.energy*20; }
  else if (st==='thermal'){ const e=0.3+ph*0.7+kick*0.4; h=((1-e)*210+e*25)%360; s=95-e*35; b=40+e*60; a=16+P.energy*26; }
  else if (st==='oil'){ h=(hbase+ph*120)%360; s=70+ph*25; b=55+ph*40; a=14+P.energy*22; }
  else if (st==='crt'){ h=(hbase+ph*40)%360; s=80; b=70+ph*30; a=18+P.energy*28; }
  else { h=(hbase+(ph-0.5)*90)%360; s=60+ph*35; b=70+ph*30; a=16+P.energy*30; }
  dst.fill((h+360)%360, s, b, a);
  dst.ellipse(S.px[i], S.py[i], sz, sz);
  // occasional bright core on the beat for sparkle
  if (!ink && kick>0.4 && fr(i+Math.floor(K.beat))<0.3){ dst.fill((h+360)%360, s*0.5, 100, a*0.9); dst.ellipse(S.px[i],S.py[i], sz*0.4, sz*0.4); }
}
dst.blendMode(BLEND);

// ---- composite dst to screen (style-dependent) ----
if (st==='crt'){
  const off = u*0.004*(1+A.rms*2);
  blendMode(ADD);
  tint(0,100,60,88); image(dst,-off,0);
  tint(120,100,60,88); image(dst,0,0);
  tint(240,100,60,88); image(dst,off,0);
  noTint(); blendMode(BLEND);
  // scanlines
  stroke(0,0,0,26); strokeWeight(1); const sp=Math.max(2,u*0.006); for(let y=0;y<height;y+=sp) line(0,y,width,y); noStroke();
} else {
  image(dst,0,0);
}
// gentle vignette on top for depth (skip ink)
if (!ink){ noStroke(); for(let r=3;r>0;r--){ fill(0,0,0,3); ellipse(width/2,height/2,width*(1.05+r*0.10),height*(1.05+r*0.10)); } }

S.a=dst; S.b=src; // swap
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0;
